migration.sql:
CREATE TYPE ticket_status AS ENUM (
  'open', 'ai_triaged', 'in_progress', 'waiting_tenant',
  'escalated', 'resolved', 'closed', 'reopened'
);

CREATE TYPE ticket_priority AS ENUM ('low', 'medium', 'high', 'critical');
CREATE TYPE ticket_channel  AS ENUM ('portal', 'whatsapp', 'email', 'admin');
CREATE TYPE audit_action    AS ENUM (
  'created', 'status_changed', 'priority_changed', 'assigned',
  'message_added', 'attachment_added', 'sla_breached',
  'escalated', 'resolved', 'closed', 'reopened', 'csat_rated'
);

table.sql:
CREATE TABLE ticket_messages (
  id          UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
  ticket_id   UUID        NOT NULL REFERENCES support_tickets(id) ON DELETE CASCADE,
  author_id   UUID        NOT NULL REFERENCES auth.users(id),
  author_role TEXT        NOT NULL CHECK (author_role IN ('tenant_user','agent','ai','system')),
  body        TEXT        NOT NULL,
  is_internal BOOLEAN     NOT NULL DEFAULT FALSE,   -- nota interna (não visível ao cliente)
  created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX idx_messages_ticket ON ticket_messages(ticket_id, created_at);

migration.sql:
-- Tickets: tenant só vê os seus próprios
ALTER TABLE support_tickets       ENABLE ROW LEVEL SECURITY;
ALTER TABLE ticket_messages       ENABLE ROW LEVEL SECURITY;
ALTER TABLE ticket_attachments    ENABLE ROW LEVEL SECURITY;
ALTER TABLE ticket_audit_log      ENABLE ROW LEVEL SECURITY;

CREATE POLICY tenant_tickets_select ON support_tickets
  FOR SELECT USING (tenant_id = auth_tenant_id() OR is_admin());

CREATE POLICY tenant_tickets_insert ON support_tickets
  FOR INSERT WITH CHECK (tenant_id = auth_tenant_id());

CREATE POLICY tenant_messages_select ON ticket_messages
  FOR SELECT USING (
    EXISTS (
      SELECT 1 FROM support_tickets t
      WHERE t.id = ticket_id
        AND (t.tenant_id = auth_tenant_id() OR is_admin())
    )
    AND (is_internal = FALSE OR is_admin())
  );

CREATE POLICY audit_log_select ON ticket_audit_log
  FOR SELECT USING (is_admin());

CREATE TRIGGER set_ticket_updated_at
  BEFORE UPDATE ON support_tickets
  FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER set_kb_updated_at
  BEFORE UPDATE ON knowledge_base_articles
  FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

